const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const uid=()=>crypto.randomUUID(), seed={tasks:[{id:'t1',title:'Plan the week ahead',body:'A little intention goes a long way. Pick your top three priorities.',status:'todo',priority:'High',date:''},{id:'t2',title:'Make space for a new idea',body:'Give that thing you’ve been thinking about a little time.',status:'todo',priority:'Normal',date:''},{id:'t3',title:'Build something you’re proud of',body:'Progress over perfection. One thoughtful step at a time.',status:'progress',priority:'High',date:''},{id:'t4',title:'Clear the desk, clear the mind',body:'A fresh start feels good.',status:'done',priority:'Low',date:''}],notes:[{id:'n1',title:'The next big thing',body:'A place to collect the ideas that won’t leave your head.\n\nStart messy. Make it real.',color:'butter',pin:true},{id:'n2',title:'A gentle reminder',body:'You don’t have to do it all today.\n\nJust the next right thing. 🌿',color:'sage',pin:true},{id:'n3',title:'Little things, big days',body:'☐ Take a proper lunch break\n☐ Step outside for a bit\n☐ Celebrate a small win',color:'rose',pin:false}],theme:'light',bg:'linen'};
let state;try{state=JSON.parse(localStorage.getItem('folio-v1'))||structuredClone(seed)}catch{state=structuredClone(seed)}let view='all',query='',editing=null,kind='task',dragging=null;
function save(){try{localStorage.setItem('folio-v1',JSON.stringify(state))}catch{toast('Storage is full. Export a backup or choose a smaller background.')}}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function applyAppearance(){document.body.classList.toggle('dark',state.theme==='dark');document.body.dataset.bg=state.bg;document.body.classList.toggle('custom-bg',!!state.wallpaper);if(state.wallpaper)document.body.style.setProperty('--wallpaper',`url("${state.wallpaper}")`);$$('[data-theme]').forEach(b=>b.classList.toggle('selected',b.dataset.theme===state.theme));$$('[data-bg]').forEach(b=>b.classList.toggle('selected',b.dataset.bg===state.bg&&!state.wallpaper))}
function render(){applyAppearance();const matches=x=>(x.title+' '+x.body).toLowerCase().includes(query);const tasks=state.tasks.filter(matches);$('#board').innerHTML=['todo','progress','done'].map((status,i)=>`<div class="column ${status}" data-status="${status}"><div class="column-heading"><span class="status-dot"></span>${['To do','In progress','Done'][i]} <small>${tasks.filter(t=>t.status===status).length}</small><button data-add="${status}" aria-label="Add task to ${status}">＋</button></div>${tasks.filter(t=>t.status===status).map(t=>`<article class="task" draggable="true" data-id="${t.id}" tabindex="0" role="button" aria-label="Edit ${esc(t.title)}"><div class="task-top"><span class="tag ${t.priority.toLowerCase()}">${esc(t.priority)} priority</span><span class="task-menu">⋯</span></div><h3>${esc(t.title)}</h3>${t.body?`<p>${esc(t.body)}</p>`:''}<div class="task-bottom"><span>◷ ${t.date?esc(new Date(t.date).toLocaleDateString(undefined,{month:'short',day:'numeric'})):'No due date'}</span>${t.date?`<button data-calendar="${t.id}" aria-label="Export calendar reminder" title="Download calendar reminder">↗</button>`:''}<button class="complete ${status==='done'?'checked':''}" data-complete="${t.id}" aria-label="${status==='done'?'Reopen':'Complete'} task">${status==='done'?'✓':''}</button></div></article>`).join('')}<button class="add-inline" data-add="${status}">＋ Add a task</button></div>`).join('');
$('#notes').innerHTML=[...state.notes].filter(matches).sort((a,b)=>b.pin-a.pin).map(n=>`<article class="note ${n.color}" data-note="${n.id}" tabindex="0" role="button" aria-label="Edit note ${esc(n.title)}"><span class="pin">${n.pin?'⌑ PINNED':'✧'}</span><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><span class="note-meta">${n.updated?'EDITED '+new Date(n.updated).toLocaleDateString(undefined,{month:'short',day:'numeric'}):'A THOUGHT WORTH KEEPING'}</span></article>`).join('')+`<button class="note paper" id="empty-note" style="border:1px dashed #a7ab9866;text-align:center;background:transparent;min-height:165px"><span style="font-size:25px;opacity:.4">＋</span><p style="margin:10px 0;color:var(--muted)">Room for another thought</p></button>`;
const done=state.tasks.filter(t=>t.status==='done').length;$('#open-stat').textContent=String(state.tasks.length-done).padStart(2,'0');$('#done-stat').textContent=String(done).padStart(2,'0');$('#notes-stat').textContent=String(state.notes.length).padStart(2,'0');$('#task-count').textContent=state.tasks.length-done;$('#note-count').textContent=state.notes.length;
$('#reminder-list').innerHTML=state.tasks.filter(t=>t.date&&t.status!=='done').sort((a,b)=>new Date(a.date)-new Date(b.date)).map(t=>`<div class="reminder-row"><div>${esc(t.title)}<small>${esc(new Date(t.date).toLocaleString())}</small></div><button class="subtle" data-calendar="${t.id}">↓ Calendar reminder</button></div>`).join('')||'<div class="reminder-row">A clear schedule. Add a date to a task to see it here.</div>';
$('#tasks-section').hidden=!['all','tasks'].includes(view);$('#notes-section').hidden=!['all','notes'].includes(view);$('#reminders-section').hidden=view!=='reminders';
}
function openEditor(type,id,status='todo'){kind=type;editing=id||null;const item=id?(type==='task'?state.tasks:state.notes).find(x=>x.id===id):{};$('#modal-title').textContent=(id?'Edit ':'Create ')+type;$('#title-input').value=item.title||'';$('#body-input').value=item.body||'';$('#task-fields').hidden=type!=='task';$('#note-fields').hidden=type!=='note';$('#status-input').value=item.status||status;$('#priority-input').value=item.priority||'Normal';$('#date-input').value=item.date||'';$('#color-input').value=item.color||'butter';$('#pin-input').checked=!!item.pin;$('#delete-item').hidden=!id;$('#editor').showModal();$('#title-input').focus()}
$('#edit-form').onsubmit=e=>{e.preventDefault();const title=$('#title-input').value.trim();if(!title){$('#title-input').focus();return}const item={id:editing||uid(),title,body:$('#body-input').value.trim(),...(kind==='task'?{status:$('#status-input').value,priority:$('#priority-input').value,date:$('#date-input').value,notified:false}:{color:$('#color-input').value,pin:$('#pin-input').checked,updated:Date.now()})};const list=kind==='task'?state.tasks:state.notes;const index=list.findIndex(x=>x.id===editing);if(index>=0)list[index]=item;else list.push(item);save();render();$('#editor').close();toast(kind==='task'?'Task saved. One step closer.':'Thought saved.');};
$('#delete-item').onclick=()=>{const key=kind==='task'?'tasks':'notes';state[key]=state[key].filter(x=>x.id!==editing);save();render();$('#editor').close();toast('Removed from your workspace.')};$('#close-modal').onclick=()=>$('#editor').close();
function download(content,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function calendar(id){const t=state.tasks.find(x=>x.id===id);if(!t?.date)return;const fmt=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const clean=s=>s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const start=new Date(t.date);download(['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Folio//Workspace//EN','BEGIN:VEVENT',`UID:${t.id}@folio.local`,`DTSTAMP:${fmt(new Date())}`,`DTSTART:${fmt(start)}`,`DTEND:${fmt(new Date(+start+1800000))}`,`SUMMARY:${clean(t.title)}`,`DESCRIPTION:${clean(t.body||'Your Folio task')}`,'BEGIN:VALARM','ACTION:DISPLAY','DESCRIPTION:Task reminder','TRIGGER:-PT10M','END:VALARM','END:VEVENT','END:VCALENDAR'].join('\r\n'),'folio-reminder.ics','text/calendar');toast('Open the downloaded file in your calendar to activate the reminder.')}
document.addEventListener('click',e=>{const el=e.target.closest('button,[data-note],.task');if(!el)return;if(el.dataset.complete){const t=state.tasks.find(t=>t.id===el.dataset.complete);t.status=t.status==='done'?'todo':'done';save();render();return}if(el.dataset.calendar){calendar(el.dataset.calendar);return}if(el.dataset.add){openEditor('task',null,el.dataset.add);return}if(el.dataset.note){openEditor('note',el.dataset.note);return}if(el.classList.contains('task')){openEditor('task',el.dataset.id);return}if(el.id==='empty-note')openEditor('note');if(el.dataset.view){view=el.dataset.view;$$('nav button').forEach(b=>b.classList.toggle('active',b===el));$('#view-title').textContent={all:'Overview',tasks:'My tasks',notes:'My notes',reminders:'Reminders'}[view];render()}if(el.dataset.theme){state.theme=el.dataset.theme;save();applyAppearance()}if(el.dataset.bg){state.bg=el.dataset.bg;delete state.wallpaper;save();applyAppearance()}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.task,.note[data-note]')){e.preventDefault();e.target.click()}});
$('#board').addEventListener('dragstart',e=>{const card=e.target.closest('.task');if(card){dragging=card.dataset.id;e.dataTransfer.setData('text/plain',dragging);e.dataTransfer.effectAllowed='move'}});$('#board').addEventListener('dragover',e=>{const col=e.target.closest('.column');if(col){e.preventDefault();$$('.column').forEach(c=>c.classList.toggle('drag-over',c===col))}});$('#board').addEventListener('drop',e=>{e.preventDefault();const col=e.target.closest('.column'),id=e.dataTransfer.getData('text/plain')||dragging;const t=state.tasks.find(t=>t.id===id);if(col&&t){t.status=col.dataset.status;save();render();toast('Task moved. Keep the momentum.')}});$('#board').addEventListener('dragend',()=>{$$('.column').forEach(c=>c.classList.remove('drag-over'));dragging=null});
$('#new-task').onclick=$('#add-task').onclick=()=>openEditor('task');$('#new-note').onclick=()=>openEditor('note');$('#search').oninput=e=>{query=e.target.value.toLowerCase();render()};$('#theme').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';save();applyAppearance()};$('#appearance').onclick=()=>$('#settings').showModal();$('#close-settings').onclick=()=>$('#settings').close();$('#reset-bg').onclick=()=>{delete state.wallpaper;state.bg='linen';save();applyAppearance()};$('#background-upload').onchange=e=>{const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Please choose an image.');return}if(file.size>2*1024*1024){toast('Choose an image smaller than 2 MB.');return}const reader=new FileReader();reader.onload=()=>{state.wallpaper=reader.result;save();applyAppearance();toast('A fresh perspective. Background updated.')};reader.readAsDataURL(file)};$('#backup').onclick=()=>download(JSON.stringify(state,null,2),'folio-backup.json','application/json');
$('#today').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});render();
setInterval(()=>{const due=state.tasks.filter(t=>t.date&&t.status!=='done'&&!t.notified&&new Date(t.date)<=new Date());for(const t of due){t.notified=true;toast('Reminder: '+t.title);if('Notification'in window&&Notification.permission==='granted')new Notification('Folio reminder',{body:t.title})}if(due.length)save()},15000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)render()});
